import{_ as a,a as t,c as n,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 81 Escape","description":"学习 分词修饰与逻辑主语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 81 Escape","description":"学习 分词修饰与逻辑主语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 分词修饰与逻辑主语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 80 The Crystal Palace","link":"/life/english/new-concept/book-2/unit-04/lesson-080"},"next":{"text":"第二册：实践与进步 · Lesson 82 Monster or fish?","link":"/life/english/new-concept/book-2/unit-04/lesson-082"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 80 The Crystal Palace","link":"/life/english/new-concept/book-2/unit-04/lesson-080"},"next":{"text":"第二册：实践与进步 · Lesson 82 Monster or fish?","link":"/life/english/new-concept/book-2/unit-04/lesson-082"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-081.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-081.md"}'),o={name:"life/english/new-concept/book-2/unit-04/lesson-081.md"};function r(i,e,l,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="第二册-实践与进步-·-lesson-81-escape" tabindex="-1">第二册：实践与进步 · Lesson 81 Escape <a class="header-anchor" href="#第二册-实践与进步-·-lesson-81-escape" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 81 Escape&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>伪装使人暂时避开注意，但动作和衣着都可能留下线索；练习分词短语与逻辑主语。本课的语言观察是：Dressed as a worker 描述主句人物的被动装扮状态，不等于正在给别人穿衣；dressing a worker 则是主动动作，意义不同。完成学习后，请写一段虚构推理场景，给出一个外表线索和一个克制的核查行动。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>prisoner</td><td>/ˈprɪzənə/</td><td>n.</td><td>囚犯</td><td>a released prisoner</td></tr><tr><td>uniform</td><td>/ˈjuːnɪfɔːm/</td><td>n.</td><td>制服</td><td>wear a uniform</td></tr><tr><td>disguise</td><td>/dɪsˈɡaɪz/</td><td>n.</td><td>伪装</td><td>in disguise</td></tr><tr><td>march</td><td>/mɑːtʃ/</td><td>v.</td><td>行进</td><td>march in line</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>in disguise — 伪装着</li><li>draw somebody&#39;s attention — 引起某人注意</li></ul><h2 id="语法讲解-分词修饰与逻辑主语" tabindex="-1">语法讲解：分词修饰与逻辑主语 <a class="header-anchor" href="#语法讲解-分词修饰与逻辑主语" aria-label="Permalink to &quot;语法讲解：分词修饰与逻辑主语&quot;">​</a></h2><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：Dressed as a worker 描述主句人物的被动装扮状态，不等于正在给别人穿衣；dressing a worker 则是主动动作，意义不同。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Dressed as a cleaner, the prisoner walked towards the side gate.</p></blockquote><p>那个囚犯扮成清洁工，向侧门走去。</p><p>Dressed 为过去分词状语，逻辑主语是 prisoner；walked 为主句谓语，towards 表方向。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Dressed as a cleaner, the gate opened 会使分词逻辑主语变成门，形成悬垂结构。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读出 dressed 的 /t/，在开头分词短语后短停，保持逻辑主语清楚。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Dressed as a cleaner, the prisoner walked towards the side gate. A guard noticed that his shoes did not match the uniform. The guard asked him to wait.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段虚构推理场景，给出一个外表线索和一个克制的核查行动。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：Dressed 为过去分词状语，逻辑主语是 prisoner；walked 为主句谓语，towards 表方向。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Dressed as a cleaner, the gate opened 会使分词逻辑主语变成门，形成悬垂结构。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>分词 Dressed as a cleaner 修饰谁？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The prisoner.</p><p><strong>解析：</strong> 分词状语通常与主句主语一致。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>守卫发现了什么不一致？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> His shoes did not match the uniform.</p><p><strong>解析：</strong> 线索是鞋与制服不匹配，不是没有制服。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改写为从句：Dressed as a cleaner, he approached the gate。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He was dressed as a cleaner when he approached the gate.</p><p><strong>解析：</strong> 展开后保留同一人物和装扮状态。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：分词修饰与逻辑主语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-080">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-082">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(o,[["render",r]]);export{u as __pageData,b as default};
